function renderStats(){const e=document.getElementById("stats-grid");e&&"undefined"!=typeof SNAKE_INFO&&(e.innerHTML=SNAKE_INFO.quickStats.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon">${e.icon}</span>\n            <div class="stat-val">${e.value}</div>\n            <div class="stat-lbl">${e.label}</div>\n        </div>\n    `).join(""))}function renderTaxonomy(){const e=document.getElementById("taxonomy-grid");if(!e||"undefined"==typeof SNAKE_INFO)return;const n=SNAKE_INFO.taxonomy,t=[{label:"Kingdom",val:n.kingdom},{label:"Phylum",val:n.phylum},{label:"Class",val:n.class},{label:"Order",val:n.order},{label:"Family",val:n.family},{label:"Genus",val:n.genus},{label:"Species",val:n.species}];e.innerHTML=t.map(e=>`\n        <div class="tax-card">\n            <span class="tax-lbl">${e.label}</span>\n            <span class="tax-val">${e.val}</span>\n        </div>\n    `).join("")}function renderProfile(){if("undefined"==typeof ECOLOGICAL_PROFILE)return;const e=ECOLOGICAL_PROFILE,n=document.getElementById("profile-overview"),t=document.getElementById("profile-dist"),o=document.getElementById("profile-behaviour"),r=document.getElementById("profile-diet"),i=document.getElementById("profile-repro"),l=document.getElementById("profile-threats"),a=document.getElementById("profile-eco");n&&(n.innerHTML=`<strong>Overview:</strong> ${e.overview}`),t&&(t.innerHTML=`<strong>Distribution & Habitat:</strong> ${e.distributionAndHabitat}`),o&&(o.innerHTML=`<strong>Behavior:</strong> ${e.behaviour}`),r&&(r.innerHTML=`<strong>Diet & Prey:</strong> ${e.diet}`),i&&(i.innerHTML=`<strong>Reproduction:</strong> ${e.reproduction}`),l&&(l.innerHTML=`<strong>Threats & Conservation Status:</strong> ${e.threatsAndConservation}`),a&&(a.innerHTML=`<strong>Ecological Importance:</strong> ${e.ecologicalImportance}`)}function renderFacts(){const e=document.getElementById("facts-list");e&&"undefined"!=typeof ECOLOGICAL_PROFILE&&(e.innerHTML=ECOLOGICAL_PROFILE.interestingFacts.map(e=>`<li>💡 ${e}</li>`).join(""))}function renderGallery(){const e=document.getElementById("gallery-grid");e&&"undefined"!=typeof GALLERY_IMAGES&&(e.innerHTML=GALLERY_IMAGES.map(e=>`\n        <div class="gallery-card">\n            <img src="${e.url}" alt="${e.caption}" loading="lazy" />\n            <p>${e.caption}</p>\n        </div>\n    `).join(""))}function renderReferences(){const e=document.getElementById("references-list");e&&"undefined"!=typeof REFERENCES&&(e.innerHTML=REFERENCES.map(e=>`\n        <li>\n            <a href="${e.link}" target="_blank" rel="noopener noreferrer">📚 ${e.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{const n=document.body.classList.toggle("light-theme");localStorage.setItem("theme",n?"light":"dark"),e.textContent=n?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderTaxonomy(),renderProfile(),renderFacts(),renderGallery(),renderReferences(),initThemeToggle()});